<?php defined('_JEXEC') or die; use Joomla\CMS\Router\Route; $e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');?>
<div class="xdecaro-scope"><div class="row g-3"><?php foreach($this->items as $item):?><div class="col-md-6 col-xl-4"><article class="xdecaro-card h-100"><div class="xdecaro-card__header"><h2 class="xdecaro-card__title"><a href="<?= Route::_('index.php?option=com_decaroevents&view=event&id='.(int)$item->id) ?>"><?= $e($item->title) ?></a></h2><p class="xdecaro-card__description"><?= $e($item->start_at) ?></p></div><div class="xdecaro-card__body"><p><?= $e($item->location) ?></p><?php if($item->event_type):?><span class="xdecaro-badge"><?= $e($item->event_type) ?></span><?php endif;?></div></article></div><?php endforeach;?></div></div>
